"use client";

// Bell with an unread badge and a small popover list. Not wired into the Header here: the app shell adds <NotificationBell />.
// Keyboard: Enter/Space opens, focus moves into the list, Esc closes and returns focus to the bell, Tab out closes it.
// Reminders are generated by the server when this list is fetched with refresh=true, so it is fetched on mount, on
// window focus and every few minutes. Failures are quiet (no badge) and never affect the rest of the page.

import { useCallback, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { useAuth } from "../Providers";
import { useWellnessSend } from "./send";
import { badgeText, plural, timeAgo } from "../../app/lib/wellness-format";
import type { AppNotification, NotificationList } from "../../app/lib/wellness-types";

export const KIND_LABEL: Record<AppNotification["kind"], string> = {
  water: "Water",
  med: "Medicine",
  winddown: "Wind-down",
  system: "Bubbles",
};

const BTN_TEXT =
  "bubbles-press inline-flex min-h-[44px] items-center justify-center gap-2 rounded-full px-4 text-body-sm font-extrabold text-bubbles-grape-deep hover:bg-tint-grape disabled:opacity-60";
const REFRESH_MS = 3 * 60 * 1000;

export function NotificationBell() {
  const { session } = useAuth();
  const send = useWellnessSend();
  const token = session?.access_token;
  const [items, setItems] = useState<AppNotification[]>([]);
  const [unread, setUnread] = useState(0);
  const [failed, setFailed] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [open, setOpen] = useState(false);
  const [announce, setAnnounce] = useState("");
  const buttonRef = useRef<HTMLButtonElement>(null);
  const popRef = useRef<HTMLDivElement>(null);
  const previousUnread = useRef(0);

  const load = useCallback(
    async (refresh: boolean) => {
      const result = await send<NotificationList>(`/notifications?limit=8&refresh=${refresh}`, "GET", undefined, { tz: false });
      if (!result.ok) {
        setFailed(true);
        setLoaded(true);
        return;
      }
      setFailed(false);
      setLoaded(true);
      const list = result.data.notifications ?? [];
      const count = typeof result.data.unread_count === "number" ? result.data.unread_count : list.filter((n) => !n.read).length;
      setItems(list);
      setUnread(count);
      if (count > previousUnread.current) setAnnounce(`You have ${plural(count, "unread notification")}.`);
      previousUnread.current = count;
    },
    [send],
  );

  useEffect(() => {
    if (!token) return;
    void load(true);
    const timer = window.setInterval(() => void load(true), REFRESH_MS);
    const onFocus = () => void load(true);
    window.addEventListener("focus", onFocus);
    return () => {
      window.clearInterval(timer);
      window.removeEventListener("focus", onFocus);
    };
  }, [token, load]);

  const close = useCallback((returnFocus: boolean) => {
    setOpen(false);
    if (returnFocus) buttonRef.current?.focus();
  }, []);

  useEffect(() => {
    if (!open) return;
    popRef.current?.focus();
    const onPointer = (e: PointerEvent) => {
      const target = e.target as Node;
      if (!popRef.current?.contains(target) && !buttonRef.current?.contains(target)) close(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") close(true);
    };
    document.addEventListener("pointerdown", onPointer);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointer);
      document.removeEventListener("keydown", onKey);
    };
  }, [open, close]);

  async function markRead(ids: string[] | "all") {
    const body = ids === "all" ? { all: true } : { ids };
    const result = await send<{ unread_count?: number }>("/notifications/read", "POST", body, { tz: false });
    if (!result.ok) {
      setFailed(true);
      return;
    }
    setItems((list) => list.map((n) => (ids === "all" || ids.includes(n.id) ? { ...n, read: true } : n)));
    const count = typeof result.data.unread_count === "number" ? result.data.unread_count : 0;
    setUnread(count);
    previousUnread.current = count;
  }

  if (!token) return null;

  const badge = badgeText(unread);
  const label = unread > 0 ? `Notifications, ${plural(unread, "unread")}` : "Notifications";

  return (
    <div className="relative">
      <button
        ref={buttonRef}
        type="button"
        aria-label={label}
        aria-expanded={open}
        aria-haspopup="dialog"
        onClick={() => {
          setOpen((v) => !v);
          if (!open) void load(false);
        }}
        className="bubbles-press relative inline-flex h-11 w-11 items-center justify-center rounded-full border-2 border-line bg-surface text-ink hover:border-line-strong"
      >
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false">
          <path d="M18 8a6 6 0 1 0-12 0c0 7-3 9-3 9h18s-3-2-3-9M13.7 21a2 2 0 0 1-3.4 0" />
        </svg>
        {badge && (
          <span aria-hidden="true" className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-bubbles-pink-ink px-1 text-[0.75rem] font-extrabold text-white">
            {badge}
          </span>
        )}
      </button>
      <div role="status" aria-live="polite" className="sr-only">
        {announce}
      </div>

      {open && (
        <div
          ref={popRef}
          role="dialog"
          aria-label="Notifications"
          tabIndex={-1}
          onBlur={(e) => {
            const next = e.relatedTarget as Node | null;
            if (next && !popRef.current?.contains(next) && !buttonRef.current?.contains(next)) close(false);
          }}
          className="absolute right-0 top-full z-[80] mt-2 w-[min(22rem,calc(100vw-2rem))] rounded-3xl border-2 border-line bg-surface p-4 shadow-lg outline-none"
        >
          <div className="flex items-center justify-between gap-2">
            <h2 className="m-0 font-display text-h4 text-default">Notifications</h2>
            {unread > 0 && (
              <button type="button" onClick={() => void markRead("all")} className={BTN_TEXT}>
                Mark all read
              </button>
            )}
          </div>

          {!loaded ? (
            <p role="status" className="m-0 mt-3 text-body-sm text-muted">
              Loading…
            </p>
          ) : failed && items.length === 0 ? (
            <div role="alert" className="mt-3 rounded-2xl bg-blush px-3 py-3 text-body-sm text-muted">
              <p className="m-0">Couldn&apos;t load notifications right now.</p>
              <button type="button" onClick={() => void load(false)} className={`${BTN_TEXT} mt-1`}>
                Try again
              </button>
            </div>
          ) : items.length === 0 ? (
            <p className="m-0 mt-3 rounded-2xl bg-blush px-3 py-3 text-body-sm text-muted">Nothing new. Gentle reminders you turn on will show up here.</p>
          ) : (
            <ul className="m-0 mt-3 flex max-h-80 list-none flex-col gap-2 overflow-y-auto p-0">
              {items.map((n) => (
                <li key={n.id} className={`rounded-2xl px-3 py-2 ${n.read ? "bg-blush" : "border-2 border-bubbles-pink bg-tint-pink"}`}>
                  <p className="m-0 text-[0.75rem] font-extrabold text-muted">
                    {KIND_LABEL[n.kind] ?? "Bubbles"} · {timeAgo(n.created_at)}
                    {!n.read && <span className="ml-2 font-extrabold text-bubbles-pink-deep">New</span>}
                  </p>
                  <p className="m-0 text-body-sm font-extrabold text-ink">{n.title}</p>
                  <p className="m-0 text-body-sm text-ink-soft">{n.body}</p>
                  {!n.read && (
                    <button type="button" onClick={() => void markRead([n.id])} className={BTN_TEXT}>
                      Mark read
                    </button>
                  )}
                </li>
              ))}
            </ul>
          )}

          <Link href="/notifications" onClick={() => close(false)} className="bubbles-press mt-3 inline-flex min-h-[44px] items-center rounded-full px-2 text-body-sm font-extrabold text-bubbles-grape-deep underline">
            See all notifications
          </Link>
        </div>
      )}
    </div>
  );
}
